-- The equipment_catalog seeded in 20260811022434_add_manual_s.sql (Goodman
-- GSZ140181K/GSZ140361K, Carrier 24ACB724A031/24VNA660-30) turned out to
-- all be DISCONTINUED, R-410A-era models superseded by the industry-wide
-- 2025 EPA AIM Act refrigerant transition to R-454B - confirmed by direct
-- web search: Goodman's own current product page
-- (goodmanmfg.com/products/heat-pumps/gszb4) lists GSZB4 as current,
-- doesn't mention GSZ14; Carrier's current residential AC lineup page
-- (carrier.com/residential/en/us/products/air-conditioners/) shows only
-- 26-prefix models (26VNA1, 26TPA8, etc.) with no 24-series models, and
-- carrier.com/residential/en/us/products/air-conditioners/24vna6/ now
-- redirects to that same current-lineup page rather than showing the
-- product. Replaced with real extended performance data for the actual
-- current-production replacement models - see equipment_catalog.source_document
-- per row for citations. Removing the old (now-incorrect) catalog rows
-- cascades to their equipment_performance_points via the FK's
-- on delete cascade.
delete from public.equipment_catalog
  where model_number in ('GSZ140181K', 'GSZ140361K', '24ACB724A031', '24VNA660-30');

with catalog_ids as (
  insert into public.equipment_catalog
    (manufacturer, model_number, equipment_type, stage_type, nominal_cooling_capacity_btu, nominal_heating_capacity_btu, rated_cfm, source_document)
  values
    ('Goodman', 'GSZB401810A', 'heat_pump', 'single', 18000, 22000, 615, 'Goodman SS-GSZB4 Expanded Cooling/Heating Data (current R-454B line, confirmed active on goodmanmfg.com/products/heat-pumps/gszb4 as of Aug 2026), https://documents.alpinehomeair.com/product/Goodman%20GSZB4%20Spec%20Sheet.pdf p.4 (cooling, IDB75/615cfm row), p.18 (heating)'),
    ('Goodman', 'GSZB403610A', 'heat_pump', 'single', 36000, 44000, 1150, 'Goodman SS-GSZB4 Expanded Cooling/Heating Data (current R-454B line, confirmed active on goodmanmfg.com/products/heat-pumps/gszb4 as of Aug 2026), https://documents.alpinehomeair.com/product/Goodman%20GSZB4%20Spec%20Sheet.pdf p.10 (cooling, IDB75/1150cfm row), p.18 (heating)'),
    ('Carrier', '26TPA824W003', 'split_ac', 'two_stage', 24000, null, 800, 'Carrier 26TPA8 Performance 18 Product Data (current R-454B line, confirmed active at carrier.com/residential/en/us/products/air-conditioners/26tpa8/ as of Aug 2026), https://assets-f02205d260.cdn.insitecloud.net/348cf726d4353c1/26TPA8-01PD.pdf, p.10 (26TPA824W003, High stage, 800 CFM row)'),
    ('Carrier', '26VNA124', 'split_ac', 'variable_speed', 24000, null, 770, 'Carrier 26VNA1 Infinity Variable Speed Air Conditioner Product Data (current R-454B line, confirmed active at carrier.com/us/en/residential/air-conditioners/26vna1/ as of Aug 2026), https://www.shareddocs.com/hvac/docs/1009/Public/00/26VNA1-01PD.pdf, p.13 (26VNA124, Maximum Demand, EDB=80F)')
  returning id, model_number
)
